	// Add indexes that make sorting faster on large tables.
	if _, err := db.Exec(`
		CREATE INDEX IF NOT EXISTS idx_subs_created_at ON subscribers(created_at);
		CREATE INDEX IF NOT EXISTS idx_subs_updated_at ON subscribers(updated_at);

